const r = await tools.exec_command({cmd:"python3 - <<'PY'
import json, statistics, os, re, math
base='results/run100'
for fn in ['metrics.jsonl','val_generations/0.jsonl','val_generations/50.jsonl','val_generations/100.jsonl','rollouts/1.jsonl','rollouts/50.jsonl','rollouts/100.jsonl']:
 p=os.path.join(base,fn); rows=[json.loads(x) for x in open(p)]
 print(fn, len(rows))
 if 'val_generations' in fn:
  scores=[r.get('score',0) for r in rows]
  print(' score mean',sum(scores)/len(scores),'n1',sum(s==1 for s in scores),'unique outputs',len(set(r.get('output','') for r in rows)),'len mean',statistics.mean(len(r.get('output','')) for r in rows))
  print(' score by chunks', [sum(scores[i:i+100])/len(scores[i:i+100]) for i in range(0,len(scores),100)][:20])
 if fn=='metrics.jsonl':
  for r in rows:
   d=r.get('data',{})
   if r['step']==0 or r['step']%10==0 or r['step']==100:
    keys=['val-core/openai/gsm8k/acc/mean@1','critic/rewards/mean','response_length/mean','response_length/clip_ratio','actor/entropy','actor/grad_norm','actor/ppo_kl','actor/loss','perf/throughput']
    print(r['step'], {k:d.get(k) for k in keys})
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:30000}); text(r.output);

