const r = await tools.exec_command({cmd:"python3 - <<'PY'
import json,re,os,collections,math
for fn in ['results/run100/val_generations/0.jsonl','results/run100/val_generations/50.jsonl','results/run100/val_generations/100.jsonl','results/run100/rollouts/1.jsonl','results/run100/rollouts/50.jsonl','results/run100/rollouts/100.jsonl']:
 rows=[json.loads(x) for x in open(fn)]
 mism=[]; dapo_scores=[]; grader=[]; nod=[]; diff=[]
 for i,r in enumerate(rows):
  out=r['output']; gt=str(r['gts']).replace(',','')
  mfull=re.findall(r'####\s*(-?[0-9][0-9,.]*)',out)
  mclip=re.findall(r'####\s*(-?[0-9.\,]+)',out[-300:])
  # Numeric compare robustly
  def norm(x):
   try:return float(x.replace(',',''))
   except:return None
  g=bool(mfull) and norm(mfull[-1])==norm(gt)
  d=bool(mclip) and norm(mclip[-1])==norm(gt)
  grader.append(g);dapo_scores.append(d)
  if g!=d: mism.append((i,r, mfull[-1] if mfull else None,mclip[-1] if mclip else None))
  if not mfull:nod.append(i)
 print('\n',fn,'n',len(rows),'frozen score',sum(float(r.get('score',0)) for r in rows)/len(rows),'grader',sum(grader)/len(rows),'dapo_clip',sum(dapo_scores)/len(rows),'mismatch',len(mism),'no_full',len(nod))
 if mism:
  for i,r,a,b in mism[:3]: print(' mismatch',i,'full',a,'clip',b,'len',len(r['output']),'frozen',r.get('score'))
PY",workdir:"/workspace",yield_time_ms:10000,max_output_tokens:20000}); text(r.output);

